/* The bug: content-box (default) */
.card {
  width: 300px;
  padding: 20px;
  border: 2px solid #ccc;
  /* rendered width = 300 + 40 + 4 = 344px -> overflows */
}

/* The fix: border-box keeps total width at 300px */
.card {
  box-sizing: border-box;
  width: 300px;
  padding: 20px;
  border: 2px solid #ccc;
  /* rendered width = 300px; content area = 256px */
}

/* Recommended global default */
*,
*::before,
*::after {
  box-sizing: border-box;
}

/* Loses: specificity (0,1,0) */
.active {
  color: red;
}

/* Wins by structure: (0,1,1) */
.nav a {
  color: #333;
}

/* FIX 1: match the structure -> (0,2,1) wins */
.nav a.active {
  color: red;
}

/* FIX 2 (modern): keep base rule at 0 specificity
   so a plain .active class can override it */
:where(.nav) a {
  color: #333; /* specificity (0,1,0) -> easy to beat */
}
.active {
  color: red; /* now wins */
}

.row {
  display: flex;
  gap: 16px;
}

.card {
  /* grow=1, shrink=1, basis=200px */
  flex: 1 1 200px;

  /* allow shrinking below content width (e.g. long text) */
  min-width: 0;
}

/* Common presets */
.fill   { flex: 1 1 0%; }   /* equal columns, ignore content size */
.rigid  { flex: 0 0 auto; } /* never grow or shrink */
.auto   { flex: 1 1 auto; } /* grow/shrink from intrinsic size */

.gallery {
  display: grid;
  gap: 1rem;
  /* as many >=250px columns as fit; stretch to fill */
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

/* Difference with only 2 cards in a wide container:
   auto-fit  -> the 2 cards stretch to fill the whole row
   auto-fill -> the 2 cards stay ~250px, empty tracks pad the rest */
.gallery--keep-slots {
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
}

.section-header {
  position: sticky;
  top: 0;            /* required: the threshold to stick at */
  background: #fff;
  z-index: 1;        /* sit above following content */
}

/* Pitfall: an ancestor with overflow clipping disables stickiness */
.scroll-parent {
  overflow: visible; /* NOT hidden/auto/scroll, or sticky won't pin */
}

/* Contrast:
   position: fixed;    -> pinned to viewport forever (e.g. global navbar)
   position: absolute; -> placed at a fixed spot in a positioned parent */

/* The trap: this ancestor makes a new stacking context */
.menu-wrapper {
  transform: translateZ(0); /* or opacity: .99, filter, will-change... */
}

.dropdown {
  position: absolute;
  z-index: 9999; /* trapped inside .menu-wrapper's context */
}

/* FIX 1: remove the context-creating property */
.menu-wrapper {
  /* transform: none; */
}

/* FIX 2: raise the ancestor's own z-index (compared at parent level) */
.menu-wrapper {
  position: relative;
  z-index: 10;
}

/* FIX 3: isolate intentionally so children stack predictably */
.card { isolation: isolate; }

/* 1. Grid - one-liner */
.parent-grid {
  display: grid;
  place-items: center; /* = justify-items + align-items */
  min-height: 100vh;
}

/* 2. Flexbox */
.parent-flex {
  display: flex;
  justify-content: center; /* main axis (horizontal by default) */
  align-items: center;     /* cross axis (vertical) */
  min-height: 100vh;
}

/* 3. Absolute + transform (unknown child size, overlays) */
.parent-abs { position: relative; }
.child-abs {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

/* Base = mobile: single column */
.cards {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Tablet and up: switch to a wrapping row */
@media (min-width: 768px) {
  .cards {
    flex-direction: row;
    flex-wrap: wrap;
  }
}

/* Desktop and up: exactly three per row */
@media (min-width: 1024px) {
  .card {
    flex: 1 1 calc((100% - 2rem) / 3);
  }
}

:root {
  --bg: #ffffff;
  --fg: #1a1a1a;
  --accent: #2563eb;
}

[data-theme="dark"] {
  --bg: #111827;
  --fg: #f3f4f6;
  --accent: #60a5fa;
}

body {
  background: var(--bg);
  color: var(--fg);
}

.btn {
  background: var(--accent, #06f); /* with fallback */
}

/* Transition: simple two-state change on hover */
.btn {
  background: #2563eb;
  transition: background 200ms ease;
}
.btn:hover {
  background: #1d4ed8;
}

/* Keyframe animation: continuous, self-running rotation */
@keyframes spin {
  to { transform: rotate(360deg); }
}
.spinner {
  width: 24px;
  height: 24px;
  border: 3px solid #ddd;
  border-top-color: #2563eb;
  border-radius: 50%;
  animation: spin 800ms linear infinite;
}

/* Required asterisk via ::after */
.label--required::after {
  content: "*";
  color: #dc2626;
  margin-left: 0.25rem;
}

/* Decorative gradient underline via ::before */
.label {
  position: relative;
}
.label::before {
  content: "";            /* required, even when empty */
  position: absolute;
  left: 0;
  bottom: -4px;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, #2563eb, #06b6d4);
}

html {
  font-size: 16px; /* 1rem = 16px; respects user override */
}

/* PROBLEM: em compounds with nesting */
.menu       { font-size: 1.2em; padding: 1em; } /* padding 19.2px */
.menu .item { font-size: 1.2em; padding: 1em; } /* font ~23px, padding ~23px! */

/* FIX: rem stays consistent regardless of nesting */
.menu       { font-size: 1.2rem; padding: 1rem; } /* padding always 16px */
.menu .item { font-size: 1rem;   padding: 1rem; }

/* Deliberate em: padding scales with THIS button's text */
.btn { font-size: 1.25rem; padding: 0.5em 1em; }

/* SLOW: animating `left` reflows every frame */
.box {
  position: absolute;
  left: 0;
  transition: left 300ms ease;
}
.box.move { left: 200px; }

/* FAST: transform is composited on the GPU (no reflow/repaint) */
.box {
  transition: transform 300ms ease;
  will-change: transform; /* hint for heavy/continuous animation */
}
.box.move { transform: translateX(200px); }

/* BEM structure */
.card { /* block */
  padding: 1rem;
}
.card__title { /* element */
  font-weight: 600;

  /* single-line truncation needs all three */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.card--featured { /* modifier */
  border: 2px solid #2563eb;
}

/* Multi-line clamp variant */
.card__title--clamp {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
